459	            let (range, bad_digits) = find_bad_digits(base, digits);
460	            // Offset by two to skip the leading `0b`/`0o`/`0x`.
461	            let sub_range = SubRange::new(range.start + 2, range.end + 2);
462	            let hint_span = DiagSpan::from_span(span, sub_range);
463	            let the_digits_are_invalid = match *bad_digits {
464	                [digit] => eco_format!("the digit `{digit}` is invalid"),
465	                [first, last] => {
466	                    eco_format!("the digits `{first}` and `{last}` are invalid")
467	                }
468	                [ref digits @ .., last] => {
